select m.*, s.dept_name as deptName
from walk_member m
left join sys_dept s on m.dept_id = s.dept_id
where m.del_flag = '0'
and m.activity_id = #{bo.activityId}
and m.dept_id = #{bo.deptId}
and m.real_name like concat('%', #{bo.realName}, '%')
and m.mobile like concat('%', #{bo.mobile}, '%')
and m.signup_status = #{bo.signupStatus}
and m.abnormal_flag = #{bo.abnormalFlag}
and m.openid = #{bo.openid}
order by m.signup_time desc

